  audioChannelCount: 2,
  audioSampleRate: 44100,
  audioSampleSizeInBits: 16,
  audioChannels: 2,
  audioFrequencyResponse: 'linear',
  audioFilterX: 0,
  audioFilterY: 0,
  audioFilterZ: 0,
  audioFilterOrder: 0
});

// Connect the audio input and output
