worklet.output.connect(audioOutput);

// Process the audio signal with the chorus effect
function processAudio(audioBuffer) {
  return worklet.processAudio(audioBuffer);
}

// Listen for audio events
audioContext.addEventListener('audio', (event) => {
  const audioBuffer = event.inputBuffer;
  const chorusBuffer = worklet.processAudio(audioBuffer);

  // Do something with the processed audio signal
