// Size returns the number of nodes in the ring
func (r *HashRing) Size() int {
    return len(r.nodes)
}

// Add adds a node to the ring
func (r *HashRing) Add(n *Node) {
    r.nodes[r.size()] = n
    r.size++
    if r.size == r.capacity {
        r.closed = true
    }
}

// Remove removes a node from the ring
func (r *HashRing) Remove(n *Node) {
    x := r.size() - 1
    for i, _ := range r.nodes {
        if r.nodes[i].HashCode() == n.HashCode() {
            x = i
